from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class OperationHistory(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    name = SchemaField(name='name', not_null=True)
    targets = SchemaField(name='targets')
    start_time = SchemaField(name='start_time', not_null=True)
    end_time = SchemaField(name='end_time')
    triggering_source = SchemaField(name='triggering_source')
    user_name = SchemaField(name='user_name', not_null=True)
    session_id = SchemaField(name='session_id', not_null=True)
    triggering_ip_address = SchemaField(name='triggering_ip_address', not_null=True)
    status = SchemaField(name='status', not_null=True)

    def __init__(self, id, name, targets, start_time, end_time, triggering_source, user_name, session_id,
                 triggering_ip_address, status):
        self.id = id
        self.name = name
        self.targets = targets
        self.start_time = start_time
        self.end_time = end_time
        self.triggering_source = triggering_source
        self.user_name = user_name
        self.session_id = session_id
        self.triggering_ip_address = triggering_ip_address
        self.status = status

        super(OperationHistory, self).__init__()

